/* User-uploaded Pharmacology Exam 2 clinical case collection. Original scenarios, keys and explanations preserved; do not use as verified clinical guidance. */
(function(){'use strict';const cases=[{"lecture":"10-11 Diabetes","topic":"Insulin choice in cats","scenario":"An 8-year-old obese spayed female DSH cat is newly diagnosed with diabetes mellitus. The owner is willing to give injections twice daily and wants the best chance of remission.","question":"Which plan is best?","options":["NPH twice daily with a high-carbohydrate diet","Regular insulin SQ every 12 hours","Glargine with a low-carbohydrate diet","Vetsulin, shaken, once daily"],"correctIndex":2,"explanation":"Glargine or another appropriately selected longer-acting insulin together with a suitable low-carbohydrate diet may improve glycemic regulation and the chance of remission in some cats. Remission is not guaranteed, and preventing symptomatic hypoglycemia remains essential. This is a general treatment principle rather than a universal promise of 80–100% remission.","difficulty":"medium","id":"E2-001","answerLetter":"C","lectureTags":["Lecture 10","Lecture 11"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"An 8-year-old obese spayed female DSH cat is newly diagnosed with diabetes mellitus. The owner is willing to give injections twice daily and wants the best chance of remission.","question":"Which plan is best?","options":["NPH twice daily with a high-carbohydrate diet","Regular insulin SQ every 12 hours","Glargine with a low-carbohydrate diet","Vetsulin, shaken, once daily"],"correctIndex":2,"explanation":"Glargine (or detemir or PZI) is a first choice in cats, and glargine plus a low-carb diet gave 80-100% remission in the studies on his slides. Remission is the primary goal in cats and is most likely in the first 6 months. NPH and Vetsulin are dog starters, and regular insulin is for DKA, not SQ maintenance."},"reviewedClinical2026":true},{"lecture":"10-11 Diabetes","topic":"Insulin choice in dogs","scenario":"A 5-year-old, 25 kg intact male Labrador is newly diagnosed with diabetes. The owner can inject twice daily.","question":"Which insulin approach is the usual starting choice?","options":["Detemir at the human dose","Glargine once daily only","Regular insulin SQ","NPH or Vetsulin twice daily, dosed per kg"],"correctIndex":3,"explanation":"In dogs requiring insulin, intermediate-acting products such as porcine lente insulin (Vetsulin) or NPH are established options, with dose and frequency individualized using glucose trends and clinical signs. Formulation concentrations, syringe compatibility and species-specific sensitivity—especially when considering detemir—must be reviewed. Do not infer safety from a generic per-kilogram rule alone.","difficulty":"medium","id":"E2-002","answerLetter":"D","lectureTags":["Lecture 10","Lecture 11"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A 5-year-old, 25 kg intact male Labrador is newly diagnosed with diabetes. The owner can inject twice daily.","question":"Which insulin approach is the usual starting choice?","options":["Detemir at the human dose","Glargine once daily only","Regular insulin SQ","NPH or Vetsulin twice daily, dosed per kg"],"correctIndex":3,"explanation":"Intermediate-acting insulins (NPH, Vetsulin) are the dog starters, dosed per kg. Detemir has normal affinity for the canine receptor but the human product is 4x concentrated, so it can cause hypoglycemic crises in dogs."},"reviewedClinical2026":true},{"lecture":"10-11 Diabetes","topic":"DKA","scenario":"A dehydrated 7-year-old diabetic dog is vomiting, lethargic, ketotic and hypokalemic.","question":"What is the best initial management approach?","options":["Give NPH SQ now","Give glargine IM","Correct fluids and electrolytes first, then start regular insulin as a CRI or IM","Withhold all insulin until ketones clear"],"correctIndex":2,"explanation":"DKA requires urgent IV fluid resuscitation, careful potassium assessment and replacement as indicated, followed by a titratable regular-insulin protocol with frequent glucose, ketone and electrolyte checks. Insulin shifts potassium intracellularly and can worsen hypokalemia. The timing and route must account for severity and patient response; do not assume that all subcutaneous absorption is impossible or use a fixed tubing-discard volume without the hospital's protocol.","difficulty":"medium","id":"E2-003","answerLetter":"C","lectureTags":["Lecture 10","Lecture 11"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A dehydrated 7-year-old diabetic dog is vomiting, lethargic, ketotic and hypokalemic.","question":"What is the best next step?","options":["Give NPH SQ now","Give glargine IM","Correct fluids and electrolytes first, then start regular insulin as a CRI or IM","Withhold all insulin until ketones clear"],"correctIndex":2,"explanation":"Electrolyte imbalance matters more than the glucose in DKA, and insulin can worsen hypokalemia, so fix K+ first. Regular insulin goes CRI or IM because SQ will not absorb in a dehydrated patient. Dump the first 50-100 mL of the CRI, since insulin sticks to the bag and tubing."},"reviewedClinical2026":true,"followUpSteps":[{"q":"After initial stabilization, the dog's blood glucose decreases while ketones remain elevated. Which ongoing plan is safest?","options":["Stop all insulin immediately whenever glucose falls.","Continue a monitored insulin protocol to resolve ketogenesis, adding dextrose as indicated while checking potassium and other electrolytes.","Replace regular insulin with a large unsupervised glargine bolus.","Give oral glucose alone and discharge."],"answer":1,"why":"DKA resolution requires suppression of ketogenesis, not just reduction of glucose. Dextrose may be added to permit continued insulin administration, with frequent ketones, glucose, acid-base status, perfusion and electrolyte checks.","tag":"Exam 2 · DKA monitoring"}]},{"lecture":"10-11 Diabetes","topic":"Somogyi effect","scenario":"A diabetic dog receiving Vetsulin has recurring PU/PD and variable home glucose readings. A recent glucose curve contains a low nadir followed by hyperglycemia. The clinician is considering changing the insulin preparation.","question":"Which action is the safest next step before deciding on an insulin switch?","options":["Increase insulin immediately because any hyperglycemia proves undertreatment.","Assume Somogyi effect and switch to PZI at the same number of units.","Use regular insulin as an unmonitored long-term replacement.","Verify the low glucose with appropriate monitoring, assess dosing/handling and clinical signs, then select a safe individualized adjustment or new insulin dose."],"correctIndex":3,"explanation":"Documented hypoglycemia is a safety concern regardless of the later glucose rebound. Review technique, insulin handling, glucose nadir and clinical signs before changing treatment. Different insulin formulations are not interchangeable unit-for-unit; a presumed Somogyi effect must not dictate a fixed switch. The imported lecture presented same-unit PZI conversion as an answer, but that is not safe general dosing guidance.","difficulty":"hard","id":"E2-004","answerLetter":"D","lectureTags":["Lecture 10","Lecture 11"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":true,"reviewFlag":"Source-specific Somogyi interpretation and same-unit insulin switching have been separated from contemporary clinical decision making.","originalUploadedCase":{"scenario":"A diabetic dog on Vetsulin has 1-2 days of good control followed by several days of PU/PD. A glucose curve shows a nadir followed by a rebound.","question":"Per Dr. Carlson, what is the next insulin choice?","options":["Increase the dose by 20%","Switch to regular insulin SQ","Add metformin","Switch to PZI at the same number of units and repeat the curve in about a week"],"correctIndex":3,"explanation":"This is the Somogyi effect: overdose causes a rapid fall and a rebound. His study guide answer is a longer-duration insulin (PZI) at the same units, because the dose may be right but is released too fast. Reducing the dose and rechecking in 2-5 days is also a standard first move."},"reviewedClinical2026":true},{"lecture":"10-11 Diabetes","topic":"Hypoglycemia in cats","scenario":"A diabetic cat on glargine looks bright and eats well. The owner is thrilled. A glucose curve shows a nadir of 48 mg/dL overnight.","question":"What is the correct interpretation?","options":["A normal appearance means the glucose is safe","Glargine cannot cause hypoglycemia","Cats can be hypoglycemic without clinical signs, so rely on glucose measurements, not appearance","Increase the dose"],"correctIndex":2,"explanation":"Cats can have low blood glucose without obvious neurologic signs, so monitoring with CGM or appropriate serial measurements is necessary. Consider glucose trends, clinical condition and appetite before adjusting insulin. The absence of signs does not rule out a dangerous nadir.","difficulty":"medium","id":"E2-005","answerLetter":"C","lectureTags":["Lecture 10","Lecture 11"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A diabetic cat on glargine looks bright and eats well. The owner is thrilled. A glucose curve shows a nadir of 48 mg/dL overnight.","question":"What is the correct interpretation?","options":["A normal appearance means the glucose is safe","Glargine cannot cause hypoglycemia","Cats can be hypoglycemic without clinical signs, so rely on glucose measurements, not appearance","Increase the dose"],"correctIndex":2,"explanation":"His study guide: relying on clinical signs is not an absolute. Glargine and detemir cause nocturnal nadirs, which is convenient because owners are home, but cats can be low without signs."},"reviewedClinical2026":true},{"lecture":"10-11 Diabetes","topic":"Acromegaly","scenario":"An 11-year-old male DSH cat with a broad face and large paws needs over 20 U of insulin per dose. Glucose occasionally crashes suddenly.","question":"What is the most likely underlying problem?","options":["Somogyi effect","Acromegaly","Hypothyroidism","Anti-insulin antibodies"],"correctIndex":1,"explanation":"Hypersomatotropism caused by excessive growth hormone is an important cause of profound feline insulin resistance, often with craniofacial enlargement and enlarged paws. Diagnosis requires appropriate evaluation, often including IGF-1 and imaging. Treatment and prognosis vary substantially; extreme insulin needs or a one-year survival estimate are not universal.","difficulty":"medium","id":"E2-006","answerLetter":"B","lectureTags":["Lecture 10","Lecture 11"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":true,"reviewFlag":"The uploaded prognosis and insulin dosing generalizations may not reflect current outcomes and treatment recommendations; verify.","originalUploadedCase":{"scenario":"An 11-year-old male DSH cat with a broad face and large paws needs over 20 U of insulin per dose. Glucose occasionally crashes suddenly.","question":"What is the most likely underlying problem?","options":["Somogyi effect","Acromegaly","Hypothyroidism","Anti-insulin antibodies"],"correctIndex":1,"explanation":"Excess somatotropin from a pituitary tumor is diabetogenic, needs very high insulin doses (up to 40 U), and its pulsatile release causes sporadic hypoglycemia. Octreotide and pegvisomant have been tried; these cats usually die within a year."},"reviewedClinical2026":true},{"lecture":"12 Thyroid","topic":"Radioiodine prep","scenario":"A 13-year-old cat with a palpable thyroid nodule and a high T4 is being considered for I-131 therapy.","question":"What pre-treatment assessment and preparation are appropriate before I-131 therapy?","options":["Start levothyroxine","Continue the Y/D diet through the procedure","Do a thyroidectomy first","Stabilize on methimazole, check metabolic, CV and renal function, then stop it 10-14 days before"],"correctIndex":3,"explanation":"Assess cardiovascular status, blood pressure, renal function and general stability before radioactive iodine treatment. Methimazole trials can help reveal masked renal disease in selected cats; the need for stabilization and medication/diet withdrawal intervals is facility-specific. Follow the I-131 center's instructions rather than imposing a universal 10–14-day rule.","difficulty":"medium","id":"E2-007","answerLetter":"D","lectureTags":["Lecture 12"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A 13-year-old cat with a palpable thyroid nodule and a high T4 is being considered for I-131 therapy.","question":"What must happen first?","options":["Start levothyroxine","Continue the Y/D diet through the procedure","Do a thyroidectomy first","Stabilize on methimazole, check metabolic, CV and renal function, then stop it 10-14 days before"],"correctIndex":3,"explanation":"The cat must be stabilized and checked for metabolic, CV and renal dysfunction. It must be off methimazole and Y/D for 10-14 days before I-131."},"reviewedClinical2026":true},{"lecture":"12 Thyroid","topic":"Pseudohypothyroidism","scenario":"A 7-year-old dog on phenobarbital for 2 years has a low total T4 on routine bloodwork. The dog is bright, with a normal coat and weight.","question":"What is the best interpretation?","options":["Likely pseudohypothyroidism from phenobarbital; no treatment is needed without clinical signs","Start lifelong levothyroxine","Start methimazole","Give I-131"],"correctIndex":0,"explanation":"Phenobarbital and some other drugs can lower total T4 measurements without genuine primary thyroid failure. Interpret results alongside clinical signs, TSH/free T4 when appropriate, and medication history; do not dismiss a concerning patient or treat solely from one laboratory number.","difficulty":"medium","id":"E2-008","answerLetter":"A","lectureTags":["Lecture 12"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A 7-year-old dog on phenobarbital for 2 years has a low total T4 on routine bloodwork. The dog is bright, with a normal coat and weight.","question":"What is the best interpretation?","options":["Likely pseudohypothyroidism from phenobarbital; no treatment is needed without clinical signs","Start lifelong levothyroxine","Start methimazole","Give I-131"],"correctIndex":0,"explanation":"Phenobarbital, glucocorticoids and sulfonamides can lower T4 without true thyroid disease. His slide notes that long-term phenobarbital is not a worry for developing true hypothyroidism. Sulfonamides used long-term can cause true hypothyroidism."},"reviewedClinical2026":true},{"lecture":"12 Thyroid","topic":"Hypothyroid dog","scenario":"A 6-year-old dog has lethargy, weight gain, cold intolerance and bilateral non-pruritic alopecia. Bloodwork shows low T4, high TSH and high cholesterol.","question":"Which treatment is the gold standard?","options":["Levothyroxine (T4) on an empty stomach","Liothyronine (T3)","Methimazole","Propranolol"],"correctIndex":0,"explanation":"Levothyroxine (T4) is standard replacement for confirmed canine hypothyroidism because tissues convert T4 to active T3, restoring thyroid signaling and feedback. T3 also participates in hypothalamic–pituitary negative feedback; the original statement that T3 provides no feedback is incorrect. Consistent formulation/administration and appropriate monitoring matter.","difficulty":"medium","id":"E2-009","answerLetter":"A","lectureTags":["Lecture 12"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A 6-year-old dog has lethargy, weight gain, cold intolerance and bilateral non-pruritic alopecia. Bloodwork shows low T4, high TSH and high cholesterol.","question":"Which treatment is the gold standard?","options":["Levothyroxine (T4) on an empty stomach","Liothyronine (T3)","Methimazole","Propranolol"],"correctIndex":0,"explanation":"T4 is used because it gives negative feedback on the hypothalamus and pituitary; T3 does not and is not used clinically. Poor response suggests an expired product or a brand switch."},"reviewedClinical2026":true},{"lecture":"12 Thyroid","topic":"Milk fever","scenario":"A Holstein cow is recumbent 12 hours after calving with cold extremities and a weak pulse.","question":"What is the treatment, and how is it prevented?","options":["Oral glucose; feed extra calcium in the dry period","IV magnesium; feed extra calcium in the dry period","IV calcium borogluconate; feed anionic salts (Cl and S) in the dry period","Oral propylene glycol; feed anionic salts after calving"],"correctIndex":2,"explanation":"Periparturient hypocalcemia produces weakness, poor perfusion and recumbency. Slow IV calcium with cardiovascular monitoring is standard treatment in clinically affected cattle; prevention depends on appropriately formulated prepartum diets, often including negative DCAD strategies. If the cow fails to rise after normocalcemia, evaluate muscle/nerve damage, other electrolyte deficits and calving injury—not simply administer antihistamines as a standard rescue.","difficulty":"medium","id":"E2-010","answerLetter":"C","lectureTags":["Lecture 12"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A Holstein cow is recumbent 12 hours after calving with cold extremities and a weak pulse.","question":"What is the treatment, and how is it prevented?","options":["Oral glucose; feed extra calcium in the dry period","IV magnesium; feed extra calcium in the dry period","IV calcium borogluconate; feed anionic salts (Cl and S) in the dry period","Oral propylene glycol; feed anionic salts after calving"],"correctIndex":2,"explanation":"Milk fever is periparturient hypocalcemia, worsened by too much dietary calcium in the dry period. If she will not rise once calcium is normal, tripelennamine or hypertonic saline can help."},"reviewedClinical2026":true},{"lecture":"13 Autonomic","topic":"Urine retention drugs","scenario":"A spayed female Labrador dribbles urine while resting. Work-up suggests poor urethral sphincter tone.","question":"Which drug and MOA fit?","options":["Oxybutynin, a muscarinic agonist","Bethanechol, a muscarinic agonist","Prazosin, an alpha-1 antagonist","Phenylpropanolamine, a non-selective alpha-1 and beta-1 agonist"],"correctIndex":3,"explanation":"Phenylpropanolamine increases adrenergic tone at the urethral closure mechanism, reducing leakage in selected dogs with urethral sphincter mechanism incompetence. Systemic sympathomimetic actions may cause hypertension, tachycardia or agitation; ensure the leakage is not due to obstruction or primary behavioral disease.","difficulty":"medium","id":"E2-011","answerLetter":"D","lectureTags":["Lecture 13"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A spayed female Labrador dribbles urine while resting. Work-up suggests poor urethral sphincter tone.","question":"Which drug and MOA fit?","options":["Oxybutynin, a muscarinic agonist","Bethanechol, a muscarinic agonist","Prazosin, an alpha-1 antagonist","Phenylpropanolamine, a non-selective alpha-1 and beta-1 agonist"],"correctIndex":3,"explanation":"Activating the SNS alpha-1 receptor raises sphincter tone and retains urine; it has some CV side effects from beta-1 activity. Oxybutynin is a muscarinic antagonist, and bethanechol and prazosin promote urination."},"reviewedClinical2026":true},{"lecture":"13 Autonomic","topic":"Urethrospasm","scenario":"A male cat with urethral obstruction has been unblocked, but straining continues from urethrospasm.","question":"Which drug is best?","options":["Bethanechol","Phenylephrine","Atropine","Tamsulosin"],"correctIndex":3,"explanation":"Tamsulosin is an alpha-1 blocker with relative lower-urinary-tract subtype selectivity, relaxing urethral smooth muscle in selected patients. A mechanically obstructed cat still needs urgent decompression and stabilization, and bethanechol should not be used to contract a bladder against an obstructed outlet.","difficulty":"medium","id":"E2-012","answerLetter":"D","lectureTags":["Lecture 13"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A male cat with urethral obstruction has been unblocked, but straining continues from urethrospasm.","question":"Which drug is best?","options":["Bethanechol","Phenylephrine","Atropine","Tamsulosin"],"correctIndex":3,"explanation":"Tamsulosin is a selective alpha-1 antagonist and is very good for urethrospasm from urethritis or urethroliths. Bethanechol is a muscarinic agonist and is contraindicated after urethral obstruction."},"reviewedClinical2026":true},{"lecture":"13 Autonomic","topic":"Ophthalmic drugs","scenario":"A dog with painful anterior uveitis is found to have elevated intraocular pressure.","question":"Which drug should be avoided?","options":["Pilocarpine","Demecarium bromide","Prazosin","Atropine"],"correctIndex":3,"explanation":"Ophthalmic atropine causes mydriasis and cycloplegia by muscarinic antagonism and may improve anterior-uveitis pain. In glaucoma, it can worsen pressure/aqueous outflow; evaluate the eye and tear-film status before using it. Horses can develop systemic antimuscarinic GI effects.","difficulty":"hard","id":"E2-013","answerLetter":"D","lectureTags":["Lecture 13"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A dog with painful anterior uveitis is found to have elevated intraocular pressure.","question":"Which drug should be avoided?","options":["Pilocarpine","Demecarium bromide","Prazosin","Atropine"],"correctIndex":3,"explanation":"Atropine is long-acting and gives comfort in uveitis, but it is contraindicated in glaucoma and dry eye. In cats use the ointment because drops cause hypersalivation. Horses: very long half-life and colic risk."},"reviewedClinical2026":true},{"lecture":"13 Autonomic","topic":"Organophosphate toxicosis","scenario":"A dog develops marked salivation, lacrimation, urination, diarrhea, dyspnea and muscle fasciculations after a confirmed organophosphate pesticide exposure.","question":"Which treatment strategy addresses both muscarinic toxicity and inhibited acetylcholinesterase?","options":["Atropine and prompt pralidoxime when appropriate, plus decontamination and airway/ventilation support.","Atropine as the sole intervention regardless of respiratory status.","Pralidoxime without treating bronchial secretions or respiratory compromise.","Neostigmine to increase acetylcholine concentrations."],"correctIndex":0,"explanation":"Organophosphates inhibit acetylcholinesterase and accumulate acetylcholine at muscarinic, nicotinic and CNS targets. Atropine counters muscarinic secretions and bronchoconstriction; pralidoxime may reactivate the enzyme before aging, with a time window varying by compound. Support ventilation and control exposure; a universal 24-hour cutoff is inaccurate.","difficulty":"medium","id":"E2-014","answerLetter":"A","lectureTags":["Lecture 13"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A dog is salivating, urinating and defecating, with dyspnea, after a flea product exposure.","question":"What is the treatment?","options":["Atropine plus pralidoxime within 24 hours","Atropine alone","Pralidoxime alone","Neostigmine"],"correctIndex":0,"explanation":"Organophosphates irreversibly inhibit AChE (SLUDD signs). Atropine blocks the muscarinic effects; pralidoxime (2-PAM) must be used within 24 hours and always with atropine."},"reviewedClinical2026":true},{"lecture":"14 Cardiovascular","topic":"Digoxin toxicity","scenario":"A dog with CHF on digoxin and furosemide is vomiting and has new ventricular ectopy.","question":"What most likely increased the digoxin toxicity risk?","options":["Furosemide-induced hypokalemia","Hyperkalemia","Hypernatremia","Hypermagnesemia"],"correctIndex":0,"explanation":"Furosemide can increase urinary potassium loss, and hypokalemia makes cardiac tissue more sensitive to digoxin-associated arrhythmias. Vomiting and new ventricular ectopy warrant immediate medication, ECG, potassium, magnesium, hydration, digoxin exposure and kidney-function review. Treat documented electrolyte or volume deficits carefully; IV fluids are not automatically appropriate in a congested CHF patient.","difficulty":"medium","id":"E2-015","answerLetter":"A","lectureTags":["Lecture 14"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"followUpSteps":[{"q":"The dog has ventricular ectopy and a low serum potassium concentration while receiving digoxin and a loop diuretic. Which monitoring priority is most appropriate?","options":["Increase digoxin to overcome the arrhythmia.","Ignore the diuretic because it cannot influence digoxin toxicity.","Reassess digoxin therapy, ECG, renal function and potassium; correct electrolyte and volume abnormalities under monitoring.","Add another loop diuretic to correct potassium."],"answer":2,"why":"Hypokalemia increases susceptibility to digoxin-associated arrhythmias. Evaluate ECG and drug exposure, kidney function and perfusion; electrolyte replacement and dose decisions need close reassessment.","tag":"Exam 2 · cardiac safety"}],"originalUploadedCase":{"scenario":"A dog with CHF on digoxin and furosemide is vomiting and has new ventricular ectopy.","question":"What most likely increased the digoxin toxicity risk?","options":["Furosemide-induced hypokalemia","Hyperkalemia","Hypernatremia","Hypermagnesemia"],"correctIndex":0,"explanation":"Digoxin toxicity is more likely when potassium is low, and many diuretics cause hypokalemia. Treat by stopping the drug, treating the arrhythmia, giving IV fluids, and carefully supplementing K+."},"reviewedClinical2026":true},{"lecture":"14 Cardiovascular","topic":"Hyperthyroid arrhythmia","scenario":"A hyperthyroid cat has a tachyarrhythmia on ECG.","question":"Which drug is best?","options":["Amlodipine","Propranolol","Digoxin","Lidocaine"],"correctIndex":1,"explanation":"Propranolol reduces beta-mediated tachycardia and can help stabilize selected hyperthyroid patients while definitive thyroid treatment is planned. Because beta-2 blockade may worsen bronchospasm, patient comorbidities and monitoring matter; beta blockade does not correct excess thyroid hormone synthesis.","difficulty":"medium","id":"E2-016","answerLetter":"B","lectureTags":["Lecture 14"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A hyperthyroid cat has a tachyarrhythmia on ECG.","question":"Which drug is best?","options":["Amlodipine","Propranolol","Digoxin","Lidocaine"],"correctIndex":1,"explanation":"Propranolol is a non-selective beta blocker. Raise the dose slowly to avoid bronchospasm from the anti-beta-2 effect."},"reviewedClinical2026":true},{"lecture":"14 Cardiovascular","topic":"Hyperthyroid hypertension","scenario":"A hyperthyroid cat has systolic blood pressure of 210 mmHg and a normal ECG rhythm.","question":"Which drug is best?","options":["Propranolol","Hydralazine","Digoxin","Amlodipine"],"correctIndex":3,"explanation":"Amlodipine preferentially blocks L-type calcium channels in vascular smooth muscle, lowering systemic blood pressure. Hyperthyroidism can contribute to hypertension, but blood-pressure measurement, target-organ assessment and treating the underlying disease remain necessary.","difficulty":"medium","id":"E2-017","answerLetter":"D","lectureTags":["Lecture 14"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A hyperthyroid cat has systolic blood pressure of 210 mmHg and a normal ECG rhythm.","question":"Which drug is best?","options":["Propranolol","Hydralazine","Digoxin","Amlodipine"],"correctIndex":3,"explanation":"Amlodipine is a calcium channel blocker, the front-line monotherapy for feline hypertension. Hydralazine is reserved for hypertensive emergencies."},"reviewedClinical2026":true},{"lecture":"14 Cardiovascular","topic":"Ventricular arrhythmia","scenario":"A Boxer in the ER has severe, sustained ventricular arrhythmia.","question":"Which drug is the best acute IV choice?","options":["Lidocaine IV","Mexiletine","Procainamide PO","Amiodarone PO"],"correctIndex":0,"explanation":"IV lidocaine is a Class IB sodium-channel blocker commonly used for certain clinically significant acute ventricular arrhythmias, with species-specific toxicity concerns. Not every ventricular ectopic beat requires antiarrhythmic therapy; treat the underlying cause and evaluate perfusion/ECG first.","difficulty":"medium","id":"E2-018","answerLetter":"A","lectureTags":["Lecture 14"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A Boxer in the ER has severe, sustained ventricular arrhythmia.","question":"Which drug is the best acute IV choice?","options":["Lidocaine IV","Mexiletine","Procainamide PO","Amiodarone PO"],"correctIndex":0,"explanation":"Lidocaine IV is the acute drug for severe ventricular arrhythmias; mexiletine and procainamide are for long-term oral therapy. Lidocaine and mexiletine bind refractory Na+ channels and are not for atrial problems."},"reviewedClinical2026":true},{"lecture":"14 Cardiovascular","topic":"Pulmonary hypertension","scenario":"A dog has echocardiographic evidence of pulmonary hypertension.","question":"Which drug is used, and how does it work?","options":["Sildenafil, a PDE5 inhibitor","Telmisartan, an angiotensin receptor blocker","Dobutamine, a beta-1 agonist","Hydralazine, a vasodilator"],"correctIndex":0,"explanation":"Sildenafil inhibits PDE5, preserving cGMP-dependent relaxation in pulmonary vascular smooth muscle and potentially lowering pulmonary vascular resistance. Underlying pulmonary/cardiac disease still requires evaluation; systemic hypotension and interacting medications may matter.","difficulty":"medium","id":"E2-019","answerLetter":"A","lectureTags":["Lecture 14"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A dog has echocardiographic evidence of pulmonary hypertension.","question":"Which drug is used, and how does it work?","options":["Sildenafil, a PDE5 inhibitor","Telmisartan, an angiotensin receptor blocker","Dobutamine, a beta-1 agonist","Hydralazine, a vasodilator"],"correctIndex":0,"explanation":"PDE5 inhibition raises cGMP in vascular smooth muscle, keeping it relaxed."},"reviewedClinical2026":true},{"lecture":"15 Respiratory","topic":"Feline asthma","scenario":"A cat has acute wheezing and respiratory distress from suspected asthma.","question":"Which drug is a selective beta-2 agonist?","options":["Atropine","Codeine","Terbutaline","Doxapram"],"correctIndex":2,"explanation":"Terbutaline is a relatively selective beta-2 agonist that increases cAMP and relaxes narrowed bronchial smooth muscle. Feline asthma also involves inflammation; respiratory distress needs stabilization, appropriate anti-inflammatory care and patient-specific bronchodilator delivery.","difficulty":"medium","id":"E2-020","answerLetter":"C","lectureTags":["Lecture 15"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A cat has acute wheezing and respiratory distress from suspected asthma.","question":"Which drug is a selective beta-2 agonist?","options":["Atropine","Codeine","Terbutaline","Doxapram"],"correctIndex":2,"explanation":"Terbutaline is oral or parenteral and used for cat asthma. Non-selective agonists (epinephrine, ephedrine, isoproterenol) also hit beta-1 and add alpha effects."},"reviewedClinical2026":true},{"lecture":"15 Respiratory","topic":"Kennel cough","scenario":"A dog with kennel cough has a harsh, dry, non-productive cough that is keeping the owner awake.","question":"Which drug is appropriate?","options":["Doxapram","Terbutaline","Hydrocodone with homatropine syrup","Atropine"],"correctIndex":2,"explanation":"For selected dogs with a severe, nonproductive cough, a centrally acting opioid antitussive may improve comfort after ruling out pneumonia or another condition where coughing is protective. Hydrocodone has sedation, respiratory and controlled-substance considerations. A routine combination syrup is not universally necessary.","difficulty":"medium","id":"E2-021","answerLetter":"C","lectureTags":["Lecture 15"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A dog with kennel cough has a harsh, dry, non-productive cough that is keeping the owner awake.","question":"Which drug is appropriate?","options":["Doxapram","Terbutaline","Hydrocodone with homatropine syrup","Atropine"],"correctIndex":2,"explanation":"Hydrocodone is a central narcotic antitussive with excellent bioavailability in dogs; homatropine lowers its abuse potential. Do not suppress a cough unless it is excessive or debilitating."},"reviewedClinical2026":true},{"lecture":"16 Renal","topic":"Spironolactone","scenario":"A dog with refractory CHF is on furosemide and an ACE inhibitor and is still edematous.","question":"Which add-on limits K+ loss and blocks aldosterone breakthrough?","options":["Spironolactone","Hydrochlorothiazide","Acetazolamide","Mannitol"],"correctIndex":0,"explanation":"Spironolactone blocks mineralocorticoid receptors and opposes aldosterone-dependent sodium retention/potassium secretion in the distal nephron; it also may reduce remodeling. Combining it with ACE inhibitors can increase hyperkalemia risk and requires renal/electrolyte monitoring. Neither drug guarantees complete RAAS blockade.","difficulty":"medium","id":"E2-022","answerLetter":"A","lectureTags":["Lecture 16"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A dog with refractory CHF is on furosemide and an ACE inhibitor and is still edematous.","question":"Which add-on limits K+ loss and blocks aldosterone breakthrough?","options":["Spironolactone","Hydrochlorothiazide","Acetazolamide","Mannitol"],"correctIndex":0,"explanation":"Spironolactone blocks the aldosterone receptor, so Na+ stays in the lumen and K+ is retained. ACE inhibition is rarely absolute, so adding it gives complete RAAS blockade. Watch for hyperkalemia; it raises digoxin half-life."},"reviewedClinical2026":true},{"lecture":"16 Renal","topic":"Udder edema","scenario":"A heifer has marked preparturient udder edema.","question":"Which pharmacologic option is discussed in the lecture for severe preparturient udder edema, assuming the clinician has determined medication is necessary?","options":["Furosemide","Dexamethasone","Hydrochlorothiazide","Mannitol"],"correctIndex":0,"explanation":"Furosemide may be considered for selected significant edema, but the underlying cause and animal's hydration/perfusion should be assessed. Food-animal drug restrictions, product labeling, milk/meat withholding and jurisdiction must be checked; the source's universal 48-hour milk withdrawal statement cannot be used for prescribing.","difficulty":"medium","id":"E2-023","answerLetter":"A","lectureTags":["Lecture 16"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A heifer has marked preparturient udder edema.","question":"Which drug is the drug of choice?","options":["Furosemide","Dexamethasone","Hydrochlorothiazide","Mannitol"],"correctIndex":0,"explanation":"Furosemide will not prematurely induce parturition (48 h milk withhold). Dexamethasone also works but induces parturition."},"reviewedClinical2026":true},{"lecture":"16 Renal","topic":"Mannitol","scenario":"A dog with head trauma has signs of raised intracranial pressure.","question":"Which diuretic is an IV emergency option?","options":["Furosemide","Spironolactone","Mannitol","Acetazolamide"],"correctIndex":2,"explanation":"Mannitol is an IV osmotic agent that increases plasma and tubular-fluid osmolality. It may acutely reduce intracranial or intraocular pressure when indicated but initially expands intravascular volume, so cardiac and renal status are critical.","difficulty":"medium","id":"E2-024","answerLetter":"C","lectureTags":["Lecture 16"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A dog with head trauma has signs of raised intracranial pressure.","question":"Which diuretic is an IV emergency option?","options":["Furosemide","Spironolactone","Mannitol","Acetazolamide"],"correctIndex":2,"explanation":"Mannitol is an osmotic diuretic that draws fluid out of the brain and eye. It is a weak diuretic that is rapidly excreted, so it is IV and emergency only; the risk is rapid volume expansion."},"reviewedClinical2026":true},{"lecture":"17 GI","topic":"Chemotherapy vomiting","scenario":"A dog develops nausea and repeated vomiting after chemotherapy. Examination finds no evidence of mechanical obstruction.","question":"Which antiemetic best targets a recognized emetic pathway in this patient's situation?","options":["Apomorphine, a D2 agonist used to induce emesis.","Ondansetron, a 5-HT3 receptor antagonist.","3% hydrogen peroxide, a gastric irritant.","Bismuth subsalicylate, which is not a primary antiemetic."],"correctIndex":1,"explanation":"Chemotherapy can stimulate serotonin release and 5-HT3 pathways, making ondansetron a rational antiemetic choice; NK1 blockade with maropitant is another common option depending on the protocol. Metoclopramide is a D2 antagonist and prokinetic, but it is not always the preferred chemotherapy antiemetic. Check hydration, concurrent therapy and obstruction risk.","difficulty":"medium","id":"E2-025","answerLetter":"B","lectureTags":["Lecture 17"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":true,"reviewFlag":"Original uploaded answer identified metoclopramide as universally preferred; current pathway-based management is more nuanced.","originalUploadedCase":{"scenario":"A dog vomits after chemotherapy. There is no obstruction.","question":"Which drug is the preferred choice and how does it work?","options":["Apomorphine, a D2 agonist","Metoclopramide, a D2 antagonist","3% hydrogen peroxide","Bismuth salicylate"],"correctIndex":1,"explanation":"Metoclopramide is the preferred drug for chemotherapy-induced vomiting and is highly effective as a CRI. A side effect is frenzied activity, and it is contraindicated with GI obstruction."},"reviewedClinical2026":true},{"lecture":"17 GI","topic":"Emesis induction","scenario":"A dog ate a handful of ibuprofen tablets 20 minutes ago and is alert.","question":"Which drug induces emesis as an eye drop, and what reverses it?","options":["Hydromorphone; reversed with naloxone","Xylazine; reversed with yohimbine","Ropinirole; reversed with metoclopramide","Apomorphine; reversed with atropine"],"correctIndex":2,"explanation":"Ophthalmic ropinirole stimulates D2 receptors involved in canine emesis. Metoclopramide is a D2 antagonist that can help stop persistent drug-induced emesis when appropriate. Emesis induction is contraindicated for some ingestions and airway-risk patients.","difficulty":"medium","id":"E2-026","answerLetter":"C","lectureTags":["Lecture 17"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A dog ate a handful of ibuprofen tablets 20 minutes ago and is alert.","question":"Which drug induces emesis as an eye drop, and what reverses it?","options":["Hydromorphone; reversed with naloxone","Xylazine; reversed with yohimbine","Ropinirole; reversed with metoclopramide","Apomorphine; reversed with atropine"],"correctIndex":2,"explanation":"Ropinirole is a D2 agonist approved as an emetic eye drop in dogs. Metoclopramide stops the vomiting once it has occurred."},"reviewedClinical2026":true},{"lecture":"17 GI","topic":"Prokinetic contraindication","scenario":"A dog has chronic vomiting. Radiographs suggest a linear foreign body. The owner has metoclopramide at home.","question":"What is correct?","options":["Give it, it will move the foreign body along","Prokinetics are contraindicated with GI obstruction","Give it with sucralfate","Use cisapride instead"],"correctIndex":1,"explanation":"Prokinetics increase smooth-muscle/enteric activity; stimulating a gut against a mechanical obstruction risks worsening distension and injury. Exclude obstruction before use and match the particular prokinetic to the segment and disorder.","difficulty":"medium","id":"E2-027","answerLetter":"B","lectureTags":["Lecture 17"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A dog has chronic vomiting. Radiographs suggest a linear foreign body. The owner has metoclopramide at home.","question":"What is correct?","options":["Give it, it will move the foreign body along","Prokinetics are contraindicated with GI obstruction","Give it with sucralfate","Use cisapride instead"],"correctIndex":1,"explanation":"All prokinetics (metoclopramide, cisapride, erythromycin, H2 blockers like ranitidine) are contraindicated with obstruction."},"reviewedClinical2026":true},{"lecture":"17 GI","topic":"Gastric ulcer","scenario":"A dog on long-term NSAIDs has hematemesis, esophagitis and melena.","question":"Which is the first-choice drug class?","options":["Sucralfate alone","Proton pump inhibitor (omeprazole or pantoprazole)","Famotidine alone","Kaolin/pectin"],"correctIndex":1,"explanation":"PPIs block the parietal H+/K+-ATPase, markedly suppressing gastric acid. Sucralfate protects exposed mucosa and requires separation from some oral drugs; misoprostol replaces prostaglandin-mediated protection but has uterotonic risks. The best agent depends on ulcer type, severity and species.","difficulty":"medium","id":"E2-028","answerLetter":"B","lectureTags":["Lecture 17"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A dog on long-term NSAIDs has hematemesis, esophagitis and melena.","question":"Which is the first-choice drug class?","options":["Sucralfate alone","Proton pump inhibitor (omeprazole or pantoprazole)","Famotidine alone","Kaolin/pectin"],"correctIndex":1,"explanation":"PPIs are first choice, especially with esophagitis. Sucralfate is a good complement but must be staggered from the PPI; misoprostol treats NSAID ulcers but not in pregnancy; H2 blockers are last."},"reviewedClinical2026":true},{"lecture":"17 GI","topic":"IBD antibiotics","scenario":"A dog has chronic enteropathy confirmed by gastrointestinal evaluation. The owner asks whether an antibiotic should be added solely because inflammation is present.","question":"Which response best reflects current antimicrobial stewardship?","options":["Prescribe enrofloxacin to every chronic enteropathy case.","Prescribe amoxicillin to every patient before a diet trial.","Use cephalexin indefinitely to reduce intestinal inflammation.","Do not prescribe antibiotics routinely; investigate diet responsiveness, parasites, cobalamin status and other causes, reserving antimicrobials for specific indications."],"correctIndex":3,"explanation":"Chronic inflammatory enteropathy does not automatically justify antibiotics. Empirical metronidazole or tylosin can cause dysbiosis and selects for resistance. A staged diagnostic/nutritional approach and appropriate follow-up are preferred; targeted antimicrobial treatment is reserved for justified bacterial or other indications.","difficulty":"medium","id":"E2-029","answerLetter":"D","lectureTags":["Lecture 17"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":true,"originalUploadedCase":{"scenario":"A dog with chronic diarrhea and biopsy-confirmed IBD needs an antibiotic with anti-inflammatory activity.","question":"Which is appropriate?","options":["Enrofloxacin","Amoxicillin","Cephalexin","Metronidazole"],"correctIndex":3,"explanation":"Metronidazole, tylosin and sulfasalazine are the IBD antibiotics. Add psyllium during therapy, then probiotics after. Check cobalamin; chronic GI disease reduces absorption and a low level delays recovery."},"reviewFlag":"Original question presupposed that an anti-inflammatory antibiotic was needed for IBD; replaced with antimicrobial-stewardship reasoning.","reviewedClinical2026":true},{"lecture":"17 GI","topic":"Acetaminophen in cats","scenario":"A cat is presented after ingesting acetaminophen.","question":"Which adjunct protects the liver?","options":["Silybin alone","Acetylcysteine","Zinc gluconate","Ursodeoxycholic acid"],"correctIndex":1,"explanation":"N-acetylcysteine supplies substrate for glutathione synthesis and helps detoxify reactive acetaminophen metabolites. In cats, acetaminophen poisoning also causes methemoglobinemia and requires urgent toxicology-directed care; NAC is not simply a generic liver supplement.","difficulty":"medium","id":"E2-030","answerLetter":"B","lectureTags":["Lecture 17"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A cat is presented after ingesting acetaminophen.","question":"Which adjunct protects the liver?","options":["Silybin alone","Acetylcysteine","Zinc gluconate","Ursodeoxycholic acid"],"correctIndex":1,"explanation":"Acetylcysteine is the adjunct for acute liver damage, including acetaminophen toxicosis in cats."},"reviewedClinical2026":true},{"lecture":"17 GI","topic":"Hepatic encephalopathy","scenario":"A young dog with a portosystemic shunt is dull and circling after a high-protein meal.","question":"Which drug is highly effective and how does it work?","options":["Lactulose, which acidifies the colon so NH3 becomes unabsorbed NH4+","Metoclopramide","Spironolactone","Omeprazole"],"correctIndex":0,"explanation":"Colonic bacterial fermentation of lactulose acidifies gut contents, shifting diffusible NH3 to poorly absorbed NH4+, while catharsis increases nitrogen elimination. Treat contributing causes and consider other adjuncts as clinically indicated.","difficulty":"medium","id":"E2-031","answerLetter":"A","lectureTags":["Lecture 17"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A young dog with a portosystemic shunt is dull and circling after a high-protein meal.","question":"Which drug is highly effective and how does it work?","options":["Lactulose, which acidifies the colon so NH3 becomes unabsorbed NH4+","Metoclopramide","Spironolactone","Omeprazole"],"correctIndex":0,"explanation":"Lactulose is not metabolized by the host; gut bacteria ferment it. Rifaximin is an adjunct that decreases urease-positive bacteria."},"reviewedClinical2026":true},{"lecture":"17 GI","topic":"Copper hepatopathy","scenario":"A West Highland White Terrier has copper-associated hepatitis.","question":"Which drugs address this?","options":["Ursodeoxycholic acid only","Lactulose","Acetylcysteine","D-penicillamine (urinary copper loss) or zinc gluconate (blocks gut absorption)"],"correctIndex":3,"explanation":"D-penicillamine chelates copper and increases its excretion in urine, while zinc reduces intestinal copper uptake. They address different stages of copper homeostasis and need hepatic, nutritional and adverse-effect monitoring.","difficulty":"medium","id":"E2-032","answerLetter":"D","lectureTags":["Lecture 17"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A West Highland White Terrier has copper-associated hepatitis.","question":"Which drugs address this?","options":["Ursodeoxycholic acid only","Lactulose","Acetylcysteine","D-penicillamine (urinary copper loss) or zinc gluconate (blocks gut absorption)"],"correctIndex":3,"explanation":"Copper chelators: D-penicillamine promotes urinary copper elimination; zinc gluconate prevents copper absorption from the gut."},"reviewedClinical2026":true},{"lecture":"18 Behavior","topic":"Rule out disease first","scenario":"A 4-year-old neutered male cat urinates outside the litter box. The owner asks for a medication.","question":"What is the best first step?","options":["Start clomipramine","Rule out medical disease (urinalysis, kidney disease), then use training with drugs as an adjunct","Start diazepam","Start selegiline"],"correctIndex":1,"explanation":"New or inappropriate elimination behavior can reflect urinary tract disease, pain, cognitive changes or stress. Medical workup and low-stress environmental management are foundational; medications may support learning but should not automatically replace behavior modification.","difficulty":"medium","id":"E2-033","answerLetter":"B","lectureTags":["Lecture 18"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A 4-year-old neutered male cat urinates outside the litter box. The owner asks for a medication.","question":"What is the best first step?","options":["Start clomipramine","Rule out medical disease (urinalysis, kidney disease), then use training with drugs as an adjunct","Start diazepam","Start selegiline"],"correctIndex":1,"explanation":"Urine marking and seizures are big clues that a behavior problem may be medical. Drugs alone are reserved for uncontrollable situational anxiety, compulsive behaviors and cognitive dysfunction."},"reviewedClinical2026":true},{"lecture":"18 Behavior","topic":"Serotonin syndrome","scenario":"A dog on fluoxetine was started on tramadol and an over-the-counter St. John's wort. It now has tremors, hyperthermia and agitation.","question":"Which intervention directly addresses excessive serotonergic signaling as part of emergency supportive management?","options":["Atipamezole","Naloxone","Cyproheptadine","Flumazenil"],"correctIndex":2,"explanation":"First stop serotonergic drugs/supplements and stabilize airway, temperature, fluids, cardiovascular and neuromuscular complications. Cyproheptadine antagonizes several serotonin receptors and may be an adjunct, not a stand-alone cure. Benzodiazepines or other measures may be needed for agitation/seizures.","difficulty":"medium","id":"E2-034","answerLetter":"C","lectureTags":["Lecture 18"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A dog on fluoxetine was started on tramadol and an over-the-counter St. John's wort. It now has tremors, hyperthermia and agitation.","question":"Which drug treats this?","options":["Atipamezole","Naloxone","Cyproheptadine","Flumazenil"],"correctIndex":2,"explanation":"Mild cases: stop the serotonergic drugs and supplements. Severe: cyproheptadine (serotonin receptor blocker), diazepam or phenobarbital for seizures and tremors, fluids, cooling. Tramadol and supplements like St. John's wort, SAMe and tryptophan contribute."},"reviewedClinical2026":true,"followUpSteps":[{"q":"The same dog becomes increasingly hyperthermic and develops rigidity and marked autonomic instability. What is the priority?","options":["Wait for cyproheptadine alone to work at home.","Continue fluoxetine because abrupt withdrawal is always worse.","Give an additional serotonergic analgesic.","Discontinue serotonergic agents and provide emergency stabilization, active temperature and seizure/agitation management, with serotonin antagonism considered as an adjunct."],"answer":3,"why":"Severe serotonin toxicity can rapidly cause hyperthermia, metabolic injury and cardiorespiratory compromise. Supportive emergency care and removal of the causative agents are essential; cyproheptadine alone is not definitive.","tag":"Exam 2 · serotonin toxicity"}]},{"lecture":"18 Behavior","topic":"Cognitive dysfunction","scenario":"A 14-year-old dog paces at night, stares at walls and has lost house training. Medical work-up is unremarkable.","question":"Which drug is the main choice, and how should it be used?","options":["Fluoxetine with clomipramine","Selegiline (Anipryl) as monotherapy","Clomipramine","Buspirone with fluoxetine"],"correctIndex":1,"explanation":"Selegiline inhibits MAO-B and can be used for canine cognitive dysfunction with environmental enrichment and medical review. Combining it with serotonergic agents such as SSRIs or TCAs may be dangerous; medication-specific washout instructions matter.","difficulty":"medium","id":"E2-035","answerLetter":"B","lectureTags":["Lecture 18"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A 14-year-old dog paces at night, stares at walls and has lost house training. Medical work-up is unremarkable.","question":"Which drug is the main choice, and how should it be used?","options":["Fluoxetine with clomipramine","Selegiline (Anipryl) as monotherapy","Clomipramine","Buspirone with fluoxetine"],"correctIndex":1,"explanation":"Selegiline is the main cognitive dysfunction drug on his slides; avoid combining it with other serotonergic drugs. Diet and enrichment are separate multimodal approaches."},"reviewedClinical2026":true},{"lecture":"18 Behavior","topic":"BDZ in cats","scenario":"A cat on daily oral diazepam for urine spraying for several weeks is now lethargic and jaundiced.","question":"What is the most likely cause?","options":["Idiosyncratic diazepam-associated hepatic necrosis.","Pancreatitis induced by a food allergy.","Bromide-associated bronchitis.","Primary renal failure caused by the drug."],"correctIndex":0,"explanation":"Oral diazepam in cats can cause rare, severe idiosyncratic hepatic necrosis. This reaction is not simply a predictable consequence of several weeks of exposure; it has been reported after relatively short administration. Emergency parenteral use for seizures has a distinct risk-benefit context.","difficulty":"medium","id":"E2-036","answerLetter":"A","lectureTags":["Lecture 18"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A cat on daily oral diazepam for urine spraying for several weeks is now lethargic and jaundiced.","question":"What is the most likely cause?","options":["Fatal idiopathic hepatic necrosis","Pancreatitis","Bronchitis","Renal failure"],"correctIndex":0,"explanation":"Do not use diazepam in cats for behavior. One or short-term doses are fine (recording); long-term use is the problem."},"reviewedClinical2026":true},{"lecture":"19 Anticonvulsants","topic":"Status epilepticus","scenario":"A dog arrives in status epilepticus.","question":"Which is an appropriate rapid first-line antiseizure intervention for this dog when IV access is available?","options":["Phenobarbital orally and wait to reassess the next day.","Levetiracetam orally as the sole immediate intervention.","An IV benzodiazepine such as diazepam or midazolam, with prompt reassessment and escalation as needed.","Begin a prolonged propofol infusion without first securing airway management."],"correctIndex":2,"explanation":"ACVIM emergency-seizure consensus supports rapid benzodiazepine rescue, including IV diazepam or midazolam; intranasal midazolam is an important option without IV access. Reassess within minutes, stabilize ABCs and metabolic disturbances, and escalate rapidly if seizure activity persists. Waiting a fixed 15 minutes or repeating 3–4 doses before reassessment is not appropriate.","difficulty":"medium","id":"E2-037","answerLetter":"C","lectureTags":["Lecture 19"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":true,"originalUploadedCase":{"scenario":"A dog arrives in status epilepticus.","question":"What is the first-choice drug?","options":["Phenobarbital PO","Levetiracetam PO","Diazepam IV","Propofol CRI"],"correctIndex":2,"explanation":"Diazepam IV every 15 minutes, directly through a catheter (it sticks to soft plastic). If it fails after 3-4 doses, phenobarbital IV, then pentobarbital, then propofol CRI. Use midazolam for a CRI. Diazepam is fine in cats for status epilepticus because use is short-term."},"reviewFlag":"Fixed 15-minute/3–4-dose lecture sequence replaced by rapid, stage-based ACVIM approach.","reviewedClinical2026":true,"followUpSteps":[{"q":"The dog continues convulsing after an appropriately administered first rescue benzodiazepine. Which response best matches emergency seizure care?","options":["Wait 15 minutes without reassessment before considering further treatment.","Reassess airway, glucose and vital signs immediately; administer the next rapid rescue intervention according to an established status-epilepticus protocol and escalate promptly.","Send home with oral phenobarbital alone.","Do not monitor temperature or oxygenation while giving anticonvulsants."],"answer":1,"why":"Status epilepticus is time-critical. ACVIM consensus recommends early stage-based rescue, rapidly checking whether the first benzodiazepine worked, addressing reversible metabolic causes and escalating without avoidable delay.","tag":"Exam 2 · status escalation"}]},{"lecture":"19 Anticonvulsants","topic":"Phenobarbital plus KBr","scenario":"A dog on phenobarbital and KBr has vomiting and abdominal pain.","question":"Which adverse condition belongs on the differential list and requires diagnostic evaluation?","options":["Bronchitis","Pancreatitis","Hepatic necrosis","Renal failure"],"correctIndex":1,"explanation":"Pancreatitis is reported with some potassium bromide and phenobarbital regimens, but vomiting and abdominal pain are nonspecific. Evaluate pancreatitis alongside medication toxicity and other gastrointestinal causes rather than assuming confirmation from symptoms alone.","difficulty":"medium","id":"E2-038","answerLetter":"B","lectureTags":["Lecture 19"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":true,"reviewFlag":"Suspected medication adverse effects require proper differential evaluation; symptoms alone do not confirm pancreatitis.","originalUploadedCase":{"scenario":"A dog on phenobarbital and KBr has vomiting and abdominal pain.","question":"Which complication is most likely?","options":["Bronchitis","Pancreatitis","Hepatic necrosis","Renal failure"],"correctIndex":1,"explanation":"Pancreatitis is the risk with KBr plus phenobarbital in dogs; bronchitis (cough) is the cat risk with KBr."},"reviewedClinical2026":true},{"lecture":"19 Anticonvulsants","topic":"Refractory seizures","scenario":"A dog on phenobarbital still seizes weekly. The vet wants to add a second drug.","question":"Which adjunct has a different principal molecular target from phenobarbital and may be considered when seizures remain inadequately controlled?","options":["Imepitoin, a GABA agonist","Another barbiturate","Daily diazepam","Levetiracetam, which blocks glutamate release"],"correctIndex":3,"explanation":"Phenobarbital primarily potentiates GABA-A receptor signaling; levetiracetam binds SV2A and modulates neurotransmitter release. Rational polytherapy balances efficacy and safety. There is no universal rule forbidding any two drugs that share a mechanism; dose and comorbidity matter.","difficulty":"medium","id":"E2-039","answerLetter":"D","lectureTags":["Lecture 19"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A dog on phenobarbital still seizes weekly. The vet wants to add a second drug.","question":"Which add-on fits the number-one rule of combination therapy?","options":["Imepitoin, a GABA agonist","Another barbiturate","Daily diazepam","Levetiracetam, which blocks glutamate release"],"correctIndex":3,"explanation":"Never use two drugs with the same MOA. Imepitoin and phenobarbital are both GABA agonists. Levetiracetam needs three-times-daily dosing and no blood monitoring."},"reviewedClinical2026":true},{"lecture":"19 Anticonvulsants","topic":"Euthanasia and rendering","scenario":"A beef cow needs humane euthanasia. The owner hopes the carcass can be accepted by a rendering service, and asks about medication residues.","question":"Which response best protects animal welfare and addresses carcass-disposal requirements?","options":["Give pentobarbital without contacting the renderer, because residues are harmless.","Use propofol alone at a routine anesthetic dose and assume death.","Use xylazine alone at a very high IV dose and assume humane euthanasia.","Use a species-appropriate AVMA-accepted euthanasia method with qualified personnel, confirm death, and coordinate residue-safe carcass disposal with the renderer and local requirements."],"correctIndex":3,"explanation":"The AVMA Guidelines do not consider xylazine or other alpha-2 agonists alone reliable humane euthanasia methods for cattle. Pentobarbital residues can poison scavengers and complicate rendering. The correct decision is an accepted humane method and explicit carcass/disposal planning, not improvising a drug-only protocol.","difficulty":"medium","id":"E2-040","answerLetter":"D","lectureTags":["Lecture 19"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":true,"reviewFlag":"Safety-critical correction: the original source presented high-dose xylazine IV as sufficient euthanasia; current AVMA guidance does not support it.","originalUploadedCase":{"scenario":"A beef cow must be euthanized, and the carcass will go to a rendering plant.","question":"Which option fits?","options":["Pentobarbital","Propofol","A very large IV dose of xylazine","Ketamine alone"],"correctIndex":2,"explanation":"Pentobarbital stays stable in carcasses, so rendering plants refuse them and carnivores can be poisoned. In cattle, more than 10 times the sedating dose of xylazine IV works."},"reviewedClinical2026":true},{"lecture":"20 Alpha-2 and others","topic":"Allergy skin testing","scenario":"A dog needs sedation for intradermal allergy skin testing.","question":"Which drug is the drug of choice, and what is unusual about its dosing?","options":["Xylazine, dosed per kg","Acepromazine, dosed per kg","Dexmedetomidine, dosed by body surface area","Detomidine, dosed per kg"],"correctIndex":2,"explanation":"Dexmedetomidine is an alpha-2 agonist used for sedation in selected veterinary protocols; atipamezole can antagonize its effects. Allergy-testing protocols vary by testing center, and sedation may affect skin responses or patient physiology. A universal body-surface-area dosing rule is not safe without the center's protocol.","difficulty":"medium","id":"E2-041","answerLetter":"C","lectureTags":["Lecture 20"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":true,"reviewFlag":"Original study-guide dosing/generalization retained only as source history; verify actual allergen testing and product dosing.","originalUploadedCase":{"scenario":"A dog needs sedation for intradermal allergy skin testing.","question":"Which drug is the drug of choice, and what is unusual about its dosing?","options":["Xylazine, dosed per kg","Acepromazine, dosed per kg","Dexmedetomidine, dosed by body surface area","Detomidine, dosed per kg"],"correctIndex":2,"explanation":"It does not interfere with the vasoactive allergen responses. Reverse with atipamezole (yohimbine also works)."},"reviewedClinical2026":true},{"lecture":"20 Alpha-2 and others","topic":"Sedating a pig","scenario":"A pig needs sedation for a procedure.","question":"Which choice works?","options":["Alfaxalone or azaperone","Xylazine","Dexmedetomidine","Detomidine"],"correctIndex":0,"explanation":"Azaperone is a butyrophenone tranquilizer used in swine in relevant jurisdictions; alfaxalone is a neuroactive steroid anesthetic that potentiates GABA-A receptors. Alpha-2 agonist responses in pigs can be variable and protocol-dependent—not universally absent. Consider food-animal restrictions and airway monitoring.","difficulty":"medium","id":"E2-042","answerLetter":"A","lectureTags":["Lecture 20"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":true,"reviewFlag":"Original assertion that no alpha-2 agonist works in swine is categorical and inaccurate.","originalUploadedCase":{"scenario":"A pig needs sedation for a procedure.","question":"Which choice works?","options":["Alfaxalone or azaperone","Xylazine","Dexmedetomidine","Detomidine"],"correctIndex":0,"explanation":"No alpha-2 agonist works in swine. Alfaxalone is a neurosteroid GABA-A modulator used as a swine sedative; azaperone is a D2 antagonist."},"reviewedClinical2026":true},{"lecture":"20 Alpha-2 and others","topic":"Acepromazine","scenario":"A Boxer arrives for an echocardiogram after the owner gave acepromazine at home to keep him calm.","question":"What is the concern?","options":["None, it improves exam quality","It raises the seizure threshold","It causes bronchoconstriction","Anti-alpha-1 effects cause hypotension; Boxers are especially sensitive, and it should not precede an in-depth CV exam"],"correctIndex":3,"explanation":"Acepromazine antagonizes dopamine D2 receptors and has alpha-1-blocking effects, producing tranquilization and potential hypotension. It has no reliable analgesia and may mask fear without treating it; cardiovascular status and individual patient response guide use.","difficulty":"medium","id":"E2-043","answerLetter":"D","lectureTags":["Lecture 20"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A Boxer arrives for an echocardiogram after the owner gave acepromazine at home to keep him calm.","question":"What is the concern?","options":["None, it improves exam quality","It raises the seizure threshold","It causes bronchoconstriction","Anti-alpha-1 effects cause hypotension; Boxers are especially sensitive, and it should not precede an in-depth CV exam"],"correctIndex":3,"explanation":"Acepromazine is a D2 antagonist with anti-alpha-1 and anti-muscarinic effects. Other cautions: seizures and temperature extremes."},"reviewedClinical2026":true},{"lecture":"20 Alpha-2 and others","topic":"Pre-purchase exam","scenario":"A buyer examines a gelding that has intermittent penile prolapse.","question":"Which prior drug is associated with persistent prolapse?","options":["Xylazine","Acepromazine","Romifidine","Butorphanol"],"correctIndex":1,"explanation":"Acepromazine's alpha-1 blockade can relax equine penile retractors and has been associated with prolonged prolapse and rare complications. Penile protrusion has other possible causes and does not independently prove drug exposure.","difficulty":"medium","id":"E2-044","answerLetter":"B","lectureTags":["Lecture 20"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A buyer examines a gelding that has intermittent penile prolapse.","question":"Which prior drug is associated with persistent prolapse?","options":["Xylazine","Acepromazine","Romifidine","Butorphanol"],"correctIndex":1,"explanation":"Equine persistent penile prolapse is a phenothiazine side effect; check when buying a stallion or gelding."},"reviewedClinical2026":true},{"lecture":"20 Opioids","topic":"Peracute analgesia","scenario":"A hit-by-car dog is stabilized and its shock is addressed. It has severe orthopedic pain.","question":"Which option provides injectable opioid analgesia for a stabilized dog with severe acute traumatic pain?","options":["Fentanyl patch","Morphine, after shock is addressed","Oral tramadol","Oral hydrocodone"],"correctIndex":1,"explanation":"Titrated injectable opioid analgesia such as morphine can be appropriate for severe acute pain after perfusion and airway assessment; other injectable full mu agonists may also be suitable. Transdermal fentanyl has delayed onset and oral tramadol is unreliable for acute severe canine pain. Monitor ventilation, nausea and hemodynamics.","difficulty":"medium","id":"E2-045","answerLetter":"B","lectureTags":["Lecture 20"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A hit-by-car dog is stabilized and its shock is addressed. It has severe orthopedic pain.","question":"Which opioid is used?","options":["Fentanyl patch","Morphine, after shock is addressed","Oral tramadol","Oral hydrocodone"],"correctIndex":1,"explanation":"Morphine is the peracute analgesic for severe trauma pain, given after stabilization. Fentanyl patches have a lag time and are not for trauma. Do not use morphine long-term."},"reviewedClinical2026":true},{"lecture":"20 Opioids","topic":"Seizure risk","scenario":"An epileptic dog needs an analgesic for osteoarthritis.","question":"Which opioid should be avoided?","options":["Butorphanol","Tramadol","Buprenorphine","Morphine"],"correctIndex":1,"explanation":"Tramadol has weak mu-opioid and monoamine reuptake effects; analgesic efficacy in dogs can be inconsistent, and seizure threshold/serotonergic interactions are concerns. Management of osteoarthritis should emphasize effective multimodal analgesia and appropriate monitoring.","difficulty":"medium","id":"E2-046","answerLetter":"B","lectureTags":["Lecture 20"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"An epileptic dog needs an analgesic for osteoarthritis.","question":"Which opioid should be avoided?","options":["Butorphanol","Tramadol","Buprenorphine","Morphine"],"correctIndex":1,"explanation":"Tramadol is the opioid most likely to cause a seizure because of its effects on catecholamine reuptake; efficacy in dogs is questionable."},"reviewedClinical2026":true},{"lecture":"20 Opioids","topic":"Loperamide in Collies","scenario":"A Collie becomes profoundly sedated after the owner gives loperamide for diarrhea.","question":"What explains this?","options":["MDR1 dysfunction lets loperamide reach the brain","Alpha-2 agonism","Dopamine blockade","GABA potentiation"],"correctIndex":0,"explanation":"ABCB1/MDR1 encodes P-glycoprotein, a transporter that helps limit CNS exposure to substances such as loperamide. Dogs with clinically important ABCB1 variants may develop opioid-like CNS toxicity after standard exposure; do not use loperamide as a diagnostic challenge.","difficulty":"hard","id":"E2-047","answerLetter":"A","lectureTags":["Lecture 20"],"source":"Uploaded Exam 2 NAVLE-style patient cases","needsReview":false,"originalUploadedCase":{"scenario":"A Collie becomes profoundly sedated after the owner gives loperamide for diarrhea.","question":"What explains this?","options":["MDR1 dysfunction lets loperamide reach the brain","Alpha-2 agonism","Dopamine blockade","GABA potentiation"],"correctIndex":0,"explanation":"Loperamide is a mu agonist normally removed from the brain by MDR1 (P-glycoprotein). Not for infectious diarrhea. His slide raises it as a possible indirect test for MDR1 dysfunction."},"reviewedClinical2026":true}];window.VPQ_PHARM_EXAM2_NAVLE_CASES=cases;
// Adapt the original uploaded questions to the existing Exam Room patient registry.
// Do not clone/rewrite the source question bank. Clinical-review flags remain visible.
window.VPQ_PHARM_EXAM2_PATIENT_FILES=cases.map(c=>{
 const allTags=Array.isArray(c.lectureTags)?c.lectureTags:[];
 const lecture=allTags.find(x=>x!=='Lecture 10')||allTags[0]||'';
 const sourceText=String(c.scenario||'');
 const animal=/\b(cat|feline|DSH|DLH)\b/i.test(sourceText)?'Cat':/\b(dog|canine|Labrador|Collie|Shepherd)\b/i.test(sourceText)?'Dog':/\b(cow|bovine|Holstein|calf)\b/i.test(sourceText)?'Cattle':/\b(horse|equine|mare|gelding)\b/i.test(sourceText)?'Horse':'Species not specified';
 return {
  id:'pharm-'+c.id.toLowerCase(),name:c.topic||'Exam 2 patient',emoji:'🐾',
  species:animal,track:'Pharmacology',lecture,lectureTags:allTags,
  intro:c.scenario,clues:'Exam 2 · '+(c.lecture||lecture),
  sourceCaseId:c.id,source:c.source,clinicalReviewRequired:!!c.needsReview,
  steps:[{q:c.question,options:c.options.slice(),answer:c.correctIndex,
   why:String(c.explanation||'')+(c.reviewFlag?'\n⚠ Clinical context: '+c.reviewFlag:'')+
   '\nStudy simulation; follow species-specific references before treating real patients.',
   tag:'Exam 2 · '+(c.difficulty||'clinical practice')}].concat((c.followUpSteps||[]).map(step=>({q:step.q,options:step.options.slice(),answer:step.answer,why:step.why,tag:step.tag||'Exam 2 · clinical follow-up'})))
 };
});
})();
